package com.tlc.crm.core.mcp.tools;

import com.tlc.commons.json.Json;
import com.tlc.commons.json.JsonObject;
import com.tlc.crm.common.converter.ConverterConfig;
import com.tlc.crm.common.iam.api.model.CrmUser;
import com.tlc.crm.core.api.product.model.converter.ProductConverter;
import com.tlc.crm.core.api.product.model.Product;
import com.tlc.crm.core.api.product.manager.ProductManager;
import com.tlc.crm.core.field.product.ProductFields;
import com.tlc.crm.core.formatter.ProductRestReqFormatter;
import com.tlc.crm.core.mcp.CrmMcpTool;
import com.tlc.crm.entity.fields.source.Source;
import com.tlc.crm.entity.models.FieldInfo;
import com.tlc.crm.entity.models.PresetConfig;
import com.tlc.crm.entity.service.FieldService;
import com.tlc.i18n.I18nResolver;
import com.tlc.i18n.service.provider.I18nServiceProvider;
import com.tlc.mcp.tool.McpTool;
import com.tlc.mcp.tool.McpToolContext;
import com.tlc.mcp.tool.McpSchemaProvider;
import com.tlc.mcp.tool.McpToolResult;
import com.tlc.mcp.tool.SchemaDefinition;
import com.tlc.mcp.tool.SchemaDefinition.FieldDef;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * MCP Tool for creating new products in CRM.
 * Accepts product details via JSON and returns the created product with generated ID.
 */
@McpTool(
    name = "create_product",
    title = "Create Product",
    description = "Create a new product using a single payload that can include both default and custom fields",
    version = "1.0"
)
public class CreateProductTool extends CrmMcpTool implements McpSchemaProvider {

    private static final Logger LOGGER = LoggerFactory.getLogger(CreateProductTool.class);
    private final ProductManager productManager;
    private final ProductConverter productConverter;
    private final ProductRestReqFormatter productRestReqFormatter;
    private final FieldService fieldService;

    public CreateProductTool() {
        this.productManager = ProductManager.getInstance();
        this.productConverter = ProductConverter.getInstance();
        this.productRestReqFormatter = ProductRestReqFormatter.getInstance();
        this.fieldService = FieldService.getSecureInstance();
    }

    public McpToolResult execute(
            McpToolContext ctx,
            Map<String, Object> payload
    ) {
        try {
            if (!authorize(ctx)) {
                return unauthorized();
            }

            CrmUser crmUser = getCrmUser(ctx);
            Long orgId = crmUser.getCrmOrg().id();

            if (payload == null || payload.isEmpty()) {
                return errorResult("Payload is required");
            }

            final List<String> missingRequired = validateRequiredFields(orgId, payload);
            if (!missingRequired.isEmpty()) {
                return errorResult("Missing required fields: " + String.join(", ", missingRequired));
            }

            final JsonObject requestJson = Json.object(payload);
            final I18nResolver i18nResolver = I18nServiceProvider.get().getResolver(Locale.getDefault());
            final JsonObject formattedProductJson = productRestReqFormatter.format(orgId, requestJson, i18nResolver);

            ConverterConfig converterConfig = new ConverterConfig(
                    orgId,
                    crmUser.getIamId(),
                    Locale.getDefault(),
                    false,
                    formattedProductJson
            );
            Product product = productConverter.convert(converterConfig, formattedProductJson);

            product.setUpdatedBy(crmUser);
            Product createdProduct = productManager.create(product);

            JsonObject responseJson = Json.object();
            responseJson.put(ProductFields.ID, createdProduct.id());
            responseJson.put(ProductFields.NAME, createdProduct.getName());
            responseJson.put(ProductFields.ORG_ID, createdProduct.orgId());

            if (createdProduct.getDescription() != null) {
                responseJson.put(ProductFields.DESCRIPTION, createdProduct.getDescription());
            }
            if (createdProduct.getSkuNumber() != null) {
                responseJson.put(ProductFields.SKU_NUMBER, createdProduct.getSkuNumber());
            }
            if (createdProduct.getProductCode() != null) {
                responseJson.put(ProductFields.PRODUCT_CODE, createdProduct.getProductCode());
            }

            LOGGER.info("Product created successfully. Org ID: {}, Product ID: {}", orgId, createdProduct.id());
            return McpToolResult.json(responseJson);

        } catch (Exception e) {
            LOGGER.error("Error creating product", e);
            return errorResult("Failed to create product: " + e.getMessage());
        }
    }

    @Override
    public SchemaDefinition inputSchema(SchemaDefinition generated) {
        final List<FieldDef> fields = new ArrayList<>(generated.fields());
        fields.add(FieldDef.builder("name").type("string").description("Product display name").required(true).minLength(1).build());
        fields.add(FieldDef.builder("prod_code").type("integer").description("Product code").required(false).build());
        fields.add(FieldDef.builder("cate").type("integer").description("Category option id").required(false).build());
        fields.add(FieldDef.builder("unit_price").type("array").description("Price rows").required(false).build());
        fields.add(FieldDef.builder("active").type("integer").description("Active status option id").required(false).build());
        fields.add(FieldDef.builder("taxable").type("integer").description("Taxable option id").required(false).build());
        fields.add(FieldDef.builder("quant_ordered").type("integer").description("Quantity ordered").required(false).build());
        fields.add(FieldDef.builder("quant_stock").type("integer").description("Quantity in stock").required(false).build());
        fields.add(FieldDef.builder("description").type("string").description("Description").required(false).build());
        fields.add(FieldDef.builder("sku_num").type("integer").description("SKU number").required(false).build());
        fields.add(FieldDef.builder("valid_till").type("string").description("ISO datetime").required(false).build());
        fields.add(FieldDef.builder("cus_text").type("string").description("Custom text example").required(false).build());
        fields.add(FieldDef.builder("cus_multiselect").type("array").description("Custom multi-select example").required(false).build());
        fields.add(FieldDef.builder("cus_monetory").type("object").description("Custom monetary example").required(false).build());
        return SchemaDefinition.of(fields);
    }

    private List<String> validateRequiredFields(Long orgId, Map<String, Object> payload) {
        final List<String> missing = new ArrayList<>();
        final List<String> requiredAliases = new ArrayList<>();
        final List<String> requiredInternalNames = new ArrayList<>();

        for (FieldInfo fieldInfo : fieldService.getFieldsBySource(orgId, Source.PRODUCT.getName())) {
            final PresetConfig presetConfig = fieldInfo.presetConfig();
            final boolean required = presetConfig.hasOverrideRequired()
                    ? presetConfig.overrideRequired()
                    : presetConfig.required();
            if (!required) {
                continue;
            }
            requiredAliases.add(fieldInfo.aliasName());
            requiredInternalNames.add(fieldInfo.getInternalName());
        }

        for (int i = 0; i < requiredAliases.size(); i++) {
            final String alias = requiredAliases.get(i);
            final String internal = requiredInternalNames.get(i);
            final boolean present = (internal != null && payload.containsKey(internal))
                    || (alias != null && payload.containsKey(alias));
            if (!present) {
                missing.add(internal != null && !internal.isBlank() ? internal : alias);
            }
        }
        return missing;
    }
}

package com.tlc.crm.core.mcp.tools;

import com.tlc.commons.json.Json;
import com.tlc.commons.json.JsonObject;
import com.tlc.crm.common.converter.ConverterConfig;
import com.tlc.crm.common.iam.api.model.CrmUser;
import com.tlc.crm.core.api.product.manager.ProductManager;
import com.tlc.crm.core.api.product.model.Product;
import com.tlc.crm.core.api.product.model.converter.ProductConverter;
import com.tlc.crm.core.field.product.ProductFields;
import com.tlc.crm.core.formatter.ProductRestReqFormatter;
import com.tlc.crm.core.mcp.CrmMcpTool;
import com.tlc.crm.entity.fields.source.Source;
import com.tlc.crm.entity.models.FieldInfo;
import com.tlc.crm.entity.models.PresetConfig;
import com.tlc.crm.entity.service.FieldService;
import com.tlc.crm.fields.models.StoreType;
import com.tlc.i18n.I18nResolver;
import com.tlc.i18n.service.provider.I18nServiceProvider;
import com.tlc.mcp.tool.McpSchemaProvider;
import com.tlc.mcp.tool.McpTool;
import com.tlc.mcp.tool.McpToolContext;
import com.tlc.mcp.tool.McpToolResult;
import com.tlc.mcp.tool.SchemaDefinition;
import com.tlc.mcp.tool.SchemaDefinition.FieldDef;
import com.tlc.mcp.tool.ToolParam;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * MCP Tool — Create Product.
 *
 * <p>Default product fields are explicit {@code @ToolParam} parameters so AI
 * clients can discover and validate them through {@code tools/list}.</p>
 *
 * <p>Org-specific custom fields (whose internal names come from
 * {@code GET /v1/field/list?source=product}) are forwarded as-is through
 * the catch-all {@code customFields} map — no key-prefix assumption is made.</p>
 *
 * <p>Required-field enforcement at runtime is driven by
 * {@link FieldService#getFieldsBySource} so it always reflects the org's
 * current field configuration.</p>
 */
@McpTool(
        name = "create_product",
        title = "Create Product",
        description = "Create a new product in the CRM. Pass default fields as named parameters. "
                + "Org-specific custom fields (internal names from /v1/field/list?source=product) "
                + "should be included directly in the arguments map.",
        version = "1.0"
)
public class CreateProductTool extends CrmMcpTool implements McpSchemaProvider {

    private static final Logger LOGGER = LoggerFactory.getLogger(CreateProductTool.class);

    private final ProductManager productManager;
    private final ProductConverter productConverter;
    private final ProductRestReqFormatter productRestReqFormatter;
    private final FieldService fieldService;

    public CreateProductTool() {
        this.productManager              = ProductManager.getInstance();
        this.productConverter            = ProductConverter.getInstance();
        this.productRestReqFormatter     = ProductRestReqFormatter.getInstance();
        this.fieldService                = FieldService.getSecureInstance();
    }

    // ─── Tool entry-point ────────────────────────────────────────────────────

    /**
     * @param ctx          MCP context (carries the resolved {@link CrmUser} identity)
     * @param name         Product display name — required by default
     * @param description  Optional description
     * @param prodCode     Product code (numeric option id or raw value)
     * @param cate         Category option id
     * @param unitPrice    Price-tag rows, e.g. [{currency:3,unit_price:"22345",tax:"12",discount:"21"}]
     * @param active       Active-status option id
     * @param taxable      Taxable option id
     * @param quantOrdered Quantity ordered
     * @param quantStock   Quantity in stock
     * @param skuNum       SKU number
     * @param validTill    Expiry in ISO-8601, e.g. 2026-07-01T12:55:00Z
     * @param customFields Catch-all — any extra key/value pairs are forwarded as
     *                     custom field values. Use the internal names returned by
     *                     {@code GET /v1/field/list?source=product}.
     */
    public McpToolResult execute(
            McpToolContext ctx,

            @ToolParam(name = "name", description = "Product display name", required = true, minLength = 1)
            String name,

            @ToolParam(name = "description", description = "Product description", required = false)
            String description,

            @ToolParam(name = "prod_code", description = "Product code", required = false)
            Long prodCode,

            @ToolParam(name = "cate", description = "Category option ID", required = false)
            Long cate,

            @ToolParam(name = "unit_price",
                    description = "Price tags array. Each entry: {currency, unit_price, tax, discount}",
                    required = false)
            List<Map<String, Object>> unitPrice,

            @ToolParam(name = "active", description = "Active-status option ID", required = false)
            Long active,

            @ToolParam(name = "taxable", description = "Taxable option ID", required = false)
            Long taxable,

            @ToolParam(name = "quant_ordered", description = "Quantity ordered", required = false)
            Long quantOrdered,

            @ToolParam(name = "quant_stock", description = "Quantity in stock", required = false)
            Long quantStock,

            @ToolParam(name = "sku_num", description = "SKU number", required = false)
            Long skuNum,

            @ToolParam(name = "valid_till",
                    description = "Expiry date-time in ISO 8601 (e.g. 2026-07-01T12:55:00Z)",
                    required = false)
            String validTill,

            // ── Catch-all: every key not matched above lands here ─────────────
            // Use field internal names from GET /v1/field/list?source=product
            Map<String, Object> customFields
    ) {
        try {
            if (!authorize(ctx)) {
                return unauthorized();
            }

            final CrmUser crmUser = getCrmUser(ctx);
            final long orgId = crmUser.getCrmOrg().id();

            // Build unified request JSON from typed params + catch-all custom fields
            final JsonObject requestJson = buildRequestJson(
                    name, description, prodCode, cate, unitPrice,
                    active, taxable, quantOrdered, quantStock, skuNum, validTill,
                    customFields);

            // Runtime required-field check driven by org's FieldService config
            final List<String> missing = validateRequiredFields(orgId, requestJson);
            if (!missing.isEmpty()) {
                return errorResult("Missing required fields: " + String.join(", ", missing));
            }

            final I18nResolver i18nResolver = I18nServiceProvider.get().getResolver(Locale.getDefault());
            final JsonObject formattedJson = productRestReqFormatter.format(orgId, requestJson, i18nResolver);

            final ConverterConfig config = new ConverterConfig(
                    orgId, crmUser.getIamId(), Locale.getDefault(), false, formattedJson);
            final Product product = productConverter.convert(config, formattedJson);
            product.setUpdatedBy(crmUser);

            final Product created = productManager.create(product);

            final JsonObject response = Json.object();
            response.put(ProductFields.ID, created.id());
            response.put(ProductFields.NAME, created.getName());
            response.put(ProductFields.ORG_ID, created.orgId());
            if (created.getDescription() != null) response.put(ProductFields.DESCRIPTION, created.getDescription());
            if (created.getSkuNumber()   != null) response.put(ProductFields.SKU_NUMBER,   created.getSkuNumber());
            if (created.getProductCode() != null) response.put(ProductFields.PRODUCT_CODE, created.getProductCode());

            LOGGER.info("Product created. Org: {}, ID: {}", orgId, created.id());
            return McpToolResult.json(response);

        } catch (Exception e) {
            LOGGER.error("Error creating product", e);
            return errorResult("Failed to create product: " + e.getMessage());
        }
    }

    // ─── McpSchemaProvider ───────────────────────────────────────────────────

    /**
     * Augments the schema derived from {@code @ToolParam} annotations with
     * any additional product fields discovered at startup via
     * {@link FieldService#getDefaultFieldsBySource}.
     *
     * <p>Field internal names (from {@link FieldInfo#getInternalName()}) are used
     * as schema keys — no hard-coded prefixes. This makes the schema correct even
     * when custom-field naming conventions differ across deployments.</p>
     */
    @Override
    public SchemaDefinition inputSchema(SchemaDefinition generated) {
        // Names already declared via @ToolParam — skip these to avoid duplicates
        final Set<String> declared = generated.fields().stream()
                .map(FieldDef::name)
                .collect(Collectors.toSet());

        final List<FieldDef> fields = new ArrayList<>(generated.fields());

        try {
            // getDefaultFieldsBySource does NOT need an orgId — returns system-level fields
            final Collection<FieldInfo> productFields = FieldService.getInstance()
                    .getDefaultFieldsBySource(List.of(Source.PRODUCT.getName()));

            for (final FieldInfo fieldInfo : productFields) {
                final String internalName = fieldInfo.getInternalName();
                if (internalName == null || internalName.isBlank()) continue;
                if (declared.contains(internalName))                  continue; // covered by @ToolParam

                final PresetConfig preset = fieldInfo.presetConfig();
                fields.add(FieldDef.builder(internalName)
                        .description(fieldInfo.fieldName())          // i18n resolved name
                        .required(preset.required())
                        .type(storeTypeToJsonSchemaType(fieldInfo.storeType()))
                        .build());
            }
        } catch (Exception e) {
            // FieldService may not be ready at registration time; schema degrades gracefully
            LOGGER.warn("Could not load product fields for schema generation: {}", e.getMessage());
        }

        return SchemaDefinition.of(fields);
    }

    // ─── Private helpers ─────────────────────────────────────────────────────

    private JsonObject buildRequestJson(
            String name, String description, Long prodCode, Long cate,
            List<Map<String, Object>> unitPrice, Long active, Long taxable,
            Long quantOrdered, Long quantStock, Long skuNum, String validTill,
            Map<String, Object> customFields) {

        final JsonObject json = Json.object();
        if (name         != null) json.put("name",          name);
        if (description  != null) json.put("description",   description);
        if (prodCode     != null) json.put("prod_code",     prodCode);
        if (cate         != null) json.put("cate",          cate);
        if (unitPrice    != null) json.put("unit_price",    Json.array(unitPrice));
        if (active       != null) json.put("active",        active);
        if (taxable      != null) json.put("taxable",       taxable);
        if (quantOrdered != null) json.put("quant_ordered", quantOrdered);
        if (quantStock   != null) json.put("quant_stock",   quantStock);
        if (skuNum       != null) json.put("sku_num",       skuNum);
        if (validTill    != null) json.put("valid_till",    validTill);
        // Org-specific custom fields — internal names vary, forward as-is
        if (customFields != null) customFields.forEach(json::put);
        return json;
    }

    /**
     * Validates required fields using the org's live FieldService configuration.
     * Checks against both the field's internal name and alias name so either form
     * of the key is accepted in the payload.
     */
    private List<String> validateRequiredFields(long orgId, JsonObject requestJson) {
        final List<String> missing = new ArrayList<>();
        try {
            for (final FieldInfo fieldInfo : fieldService.getFieldsBySource(orgId, Source.PRODUCT.getName())) {
                final PresetConfig preset = fieldInfo.presetConfig();
                // Honour overrideRequired if set; otherwise fall back to the base required flag
                final boolean required = preset.hasOverrideRequired()
                        ? preset.overrideRequired()
                        : preset.required();
                if (!required) continue;

                final String internalName = fieldInfo.getInternalName();
                final String alias        = fieldInfo.aliasName();
                final boolean present =
                        (internalName != null && requestJson.containsKey(internalName))
                        || (alias != null && requestJson.containsKey(alias));

                if (!present) {
                    missing.add(internalName != null && !internalName.isBlank() ? internalName : alias);
                }
            }
        } catch (Exception e) {
            LOGGER.warn("Required-field validation failed: {}", e.getMessage());
        }
        return missing;
    }

    /** Maps a CRM {@link StoreType} to a JSON Schema primitive type string. */
    private String storeTypeToJsonSchemaType(StoreType storeType) {
        if (storeType == null) return "string";
        return switch (storeType) {
            case MULTI_SELECT, PRICE_TAGS                          -> "array";
            case MONETARY, DATE_RANGE, DATE_TIME_RANGE             -> "object";
            case NUMBER, DROPDOWN, OWNER, COMPANY, CONTACT         -> "integer";
            default                                                -> "string";
        };
    }
}

package com.tlc.crm.common.cdc;

import com.tlc.cdc.core.event.CdcEventHandler;
import com.tlc.cdc.core.manager.CdcConnectorManager;
import com.tlc.cdc.core.models.AggregatedCdcEventRequest;
import com.tlc.cdc.core.models.ConnectorConfig;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Abstract base implementation of {@link CdcEventHandler} for CRM-related Change Data Capture (CDC) events.
 *
 * <p>This class provides common functionality required for handling CDC events
 * originating from CRM tables. Concrete implementations should extend this
 * class and implement the necessary logic to process specific CRM entities
 * and enrich or transform the incoming CDC records.</p>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public abstract class CrmCdcEventHandler implements CdcEventHandler {

    protected static final Logger LOGGER = LoggerFactory.getLogger(CrmCdcEventHandler.class);

    protected final CrmCdcPublisher cdcPublisher;
    protected final CdcConnectorManager cdcConnectorManager;

    protected CrmCdcEventHandler() {
        this.cdcPublisher = CrmCdcPublisher.getInstance();
        this.cdcConnectorManager = CdcConnectorManager.getInstance();
    }

    /**
     * {@inheritDoc}
     *
     * @param aggregatedCdcEventRequest The aggregated CDC event containing transaction metadata and processed payload.
     */
    @Override
    public void handle(final AggregatedCdcEventRequest aggregatedCdcEventRequest) {


        secureHandle(aggregatedCdcEventRequest);
    }

    /**
     * Handles the processing of the aggregated CDC event request in a secure manner.
     *
     * @param aggregatedCdcEventRequest The aggregated CDC event containing transaction metadata and processed payload.
     */
    protected abstract void secureHandle(final AggregatedCdcEventRequest aggregatedCdcEventRequest);
}

package com.tlc.crm.common.cdc;

import com.tlc.cdc.core.event.CdcEventHandler;
import com.tlc.cdc.core.manager.CdcConnectorManager;
import com.tlc.cdc.core.models.AggregatedCdcEventRequest;
import com.tlc.cdc.core.models.ConnectorConfig;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Abstract base implementation of {@link CdcEventHandler} for CRM-related Change Data Capture (CDC) events.
 *
 * <p>This class provides common functionality required for handling CDC events
 * originating from CRM tables. Concrete implementations should extend this
 * class and implement the necessary logic to process specific CRM entities
 * and enrich or transform the incoming CDC records.</p>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public abstract class CrmCdcEventHandler implements CdcEventHandler {

    protected static final Logger LOGGER = LoggerFactory.getLogger(CrmCdcEventHandler.class);

    protected final CrmCdcPublisher cdcPublisher;
    protected final CdcConnectorManager cdcConnectorManager;

    protected CrmCdcEventHandler() {
        this.cdcPublisher = CrmCdcPublisher.getInstance();
        this.cdcConnectorManager = CdcConnectorManager.getInstance();
    }

    /**
     * {@inheritDoc}
     *
     * @param aggregatedCdcEventRequest The aggregated CDC event containing transaction metadata and processed payload.
     */
    @Override
    public void handle(final AggregatedCdcEventRequest aggregatedCdcEventRequest) {
        try {
            secureHandle(aggregatedCdcEventRequest);
        } catch (final Exception exception) {
            LOGGER.error("CDC: Error occurred while handling aggregated CDC event. ID: {}, Reason: {}",
                    aggregatedCdcEventRequest.id(), exception.getMessage(), exception);

            for (final ConnectorConfig connectorConfig : cdcConnectorManager.getAll(ConnectorConfig.Type.SOURCE)) {
                final String dlqTopic = String.join("-", "dlq", connectorConfig.name().trim());

                LOGGER.warn("CDC: Publishing failed event data to DLQ topic: {}, ID: {}", dlqTopic, aggregatedCdcEventRequest.id());
                cdcPublisher.publishToDlq(dlqTopic, aggregatedCdcEventRequest.data());
            }
        }
    }

    /**
     * Handles the processing of the aggregated CDC event request in a secure manner.
     *
     * @param aggregatedCdcEventRequest The aggregated CDC event containing transaction metadata and processed payload.
     */
    protected abstract void secureHandle(final AggregatedCdcEventRequest aggregatedCdcEventRequest);
}

package com.tlc.crm.zapier.internal.action.dispatcher;

import com.tlc.commons.code.ErrorCode;
import com.tlc.commons.json.JsonObject;

import com.tlc.crm.common.action.CrmResponse;
import com.tlc.crm.common.converter.ConverterConfig;
import com.tlc.crm.common.models.Action;

import com.tlc.crm.core.api.deal.manager.DealManager;
import com.tlc.crm.core.api.deal.manager.ProductDetailsHolderManager;
import com.tlc.crm.core.api.deal.manager.PipelineStageManager;
import com.tlc.crm.core.api.deal.model.Deal.State;
import com.tlc.crm.core.api.deal.model.PipelineStage;
import com.tlc.crm.core.api.deal.model.Deal;
import com.tlc.crm.core.api.deal.model.ProductDetail;
import com.tlc.crm.core.api.deal.model.ProductDetailsHolder;
import com.tlc.crm.core.api.deal.model.converter.DealConverter;
import com.tlc.crm.core.api.deal.model.converter.ProductDetailsHolderConverter;
import com.tlc.crm.core.field.deal.DealFields;

import com.tlc.crm.entity.fields.source.Source;

import com.tlc.crm.zapier.api.models.ZapActionRequestContext;
import com.tlc.crm.zapier.fields.ZapAttributes;
import com.tlc.crm.zapier.internal.action.formatter.DealZapActionJsonFormatter;
import com.tlc.crm.zapier.internal.status.ZapierErrorCodes;

import com.tlc.validator.type.Group;

import java.util.Collection;
import java.util.Objects;
import java.util.Optional;

/**
 * Implementation of {@link DealZapActionDispatcher} for handling
 * Zapier actions related to deal entities.
 *
 * @author ThalaimalaiPandiyanT
 * @version 1.0
 */
public final class DealZapActionDispatcher extends AbstractSourceZapActionDispatcher {

    private final DealConverter dealConverter;
    private final DealManager dealManager;
    private final ProductDetailsHolderConverter productDetailsHolderConverter;
    private final ProductDetailsHolderManager productDetailsHolderManager;
    private final DealZapActionJsonFormatter dealZapActionJsonFormatter;

    private DealZapActionDispatcher() {
        this.dealConverter = DealConverter.getInstance();
        this.dealManager = DealManager.getInstance();
        this.productDetailsHolderConverter = ProductDetailsHolderConverter.getInstance();
        this.productDetailsHolderManager = ProductDetailsHolderManager.getInstance();
        this.dealZapActionJsonFormatter = DealZapActionJsonFormatter.getInstance();
    }

    private static final class Instance {
        private static final DealZapActionDispatcher ZAP_ACTION_DISPATCHER = new DealZapActionDispatcher();
    }

    public static DealZapActionDispatcher getInstance() {
        return Instance.ZAP_ACTION_DISPATCHER;
    }

    /**
     * {@inheritDoc}
     *
     * @param zapActionRequestContext The context containing the request, response, and action details.
     */
    @Override
    public void dispatch(final ZapActionRequestContext zapActionRequestContext) {
        switch (zapActionRequestContext.getZapAction()) {
            case CREATE_DEAL -> create(zapActionRequestContext);
            case UPDATE_DEAL -> update(zapActionRequestContext);
            case ADD_PRODUCT_TO_DEAL -> addProductToDeal(zapActionRequestContext);
        }
    }

    /**
     * Handles the creation logic for a Zapier action using the provided request context.
     *
     * @param zapActionRequestContext The context containing request data, metadata, and utilities needed to perform the action.
     */
    private void create(final ZapActionRequestContext zapActionRequestContext) {
        final Long orgId = zapActionRequestContext.getOrgId();
        final CrmResponse response = zapActionRequestContext.getResponse();
        final JsonObject dealJson = dealZapActionJsonFormatter.format(orgId, zapActionRequestContext.getZapAction(), zapActionRequestContext.getJsonObject());
        final Deal deal = dealConverter.convert(new ConverterConfig(orgId, zapActionRequestContext.getUserId(), null, false, dealJson), dealJson);
        final Collection<String> errors = validate(deal, Group.Create.class);

        if (errors.isEmpty()) {
            try {
                dealManager.create(deal);
                index(orgId, deal, Action.CREATE);

                response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.create.success"));
                response.send();
            } catch (Throwable throwable) {
                LOGGER.error("Zapier Action Execution: Failed to execute the deal create action. OrgId: {}, Reason: {}", orgId, throwable.getMessage());

                response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.create.failed"));
                response.setErrorCode(ErrorCode.get(ZapierErrorCodes.CREATE_ACTION_FAILED));
                response.send();
            }
        } else {
            response.setErrorCode(ErrorCode.get(ZapierErrorCodes.DATA_VALIDATION_FAILED));
            response.put(ZapAttributes.ERRORS, errors);
            response.send();
        }
    }

    /**
     * Performs an update operation for a Zapier action using the provided request context.
     *
     * @param zapActionRequestContext The context containing data and parameters required to update the target entity.
     */
    private void update(final ZapActionRequestContext zapActionRequestContext) {
        final Long orgId = zapActionRequestContext.getOrgId();
        final CrmResponse response = zapActionRequestContext.getResponse();
        final JsonObject dealJson = dealZapActionJsonFormatter.format(orgId, zapActionRequestContext.getZapAction(), zapActionRequestContext.getJsonObject());

        if (dealManager.exists(orgId, dealJson.getLong(ZapAttributes.ID))) {
            final Deal deal = dealConverter.convert(new ConverterConfig(orgId, zapActionRequestContext.getUserId(), null, true, dealJson), dealJson);
            final Collection<String> errors = validate(deal, Group.Update.class);

            if (errors.isEmpty()) {
                try {
                    setDealState(orgId, deal);
                    dealManager.update(deal);
                    index(orgId, deal, Action.UPDATE);

                    response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.update.success"));
                    response.send();
                } catch (Throwable throwable) {
                    LOGGER.error("Zapier Action Execution: Failed to execute the deal update action. OrgId: {}, Reason: {}", orgId, throwable.getMessage());

                    response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.update.failed"));
                    response.setErrorCode(ErrorCode.get(ZapierErrorCodes.UPDATE_ACTION_FAILED));
                    response.send();
                }
            } else {
                response.setErrorCode(ErrorCode.get(ZapierErrorCodes.DATA_VALIDATION_FAILED));
                response.put(ZapAttributes.ERRORS, errors);
                response.send();
            }
        } else {
            response.setErrorCode(ErrorCode.get(ZapierErrorCodes.ENTITY_NOT_FOUND));
            response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.entity.invalid"));
            response.send();
        }
    }

    /**
     * Sets the state of the given deal for the specified organization.
     *
     * @param orgId The ID of the organization to which the deal belongs.
     * @param deal  The {@link Deal} object whose state is to be updated.
     */
    private void setDealState(final Long orgId, final Deal deal) {
        final PipelineStage pipelineStage = deal.getPipelineStage();

        if (Objects.nonNull(pipelineStage)) {
            final String pipelineStageName = PipelineStageManager.getInstance().get(orgId, pipelineStage.id()).getName();

            if (Objects.nonNull(pipelineStageName)) {
                deal.setState(Deal.State.getStateByName(pipelineStageName));
            }
            final State state = deal.getState();

            switch (state) {
                case WON -> {
                    if (Objects.isNull(deal.getWonReason())) {
                        fieldService.getDefaultFieldByAliasName(Source.DEAL, DealFields.WON_REASON)
                                .ifPresent(fieldInfo -> optionService.get(orgId, fieldInfo).stream().findFirst().ifPresent(deal::setWonReason));
                    }
                }
                case LOST -> {
                    if (Objects.isNull(deal.getLostReason())) {
                        fieldService.getDefaultFieldByAliasName(Source.DEAL, DealFields.LOST_REASON.getName())
                                .ifPresent(fieldInfo -> optionService.get(orgId, fieldInfo).stream().findFirst().ifPresent(deal::setLostReason));
                    }
                }
            }
        }
    }

    /**
     * Adds a product to an existing deal using the provided Zapier action context.
     *
     * @param zapActionRequestContext The context containing deal and product data required to perform the operation.
     */
    private void addProductToDeal(final ZapActionRequestContext zapActionRequestContext) {
        final Long orgId = zapActionRequestContext.getOrgId();
        final Long userId = zapActionRequestContext.getUserId();
        final CrmResponse response = zapActionRequestContext.getResponse();

        try {
            final JsonObject productDetailsJson = dealZapActionJsonFormatter.formatAddProductJson(orgId, zapActionRequestContext.getZapAction(), zapActionRequestContext.getJsonObject());
            final ProductDetailsHolder existingProductDetailsHolder = productDetailsHolderManager.getLinkedProductList(orgId, productDetailsJson.getLong(ZapAttributes.DEAL_ID), false);
            final ProductDetailsHolder productDetailsHolder = productDetailsHolderConverter.convert(new ConverterConfig(orgId, userId, null, false, productDetailsJson), productDetailsJson);
            final Collection<ProductDetail> productDetails = productDetailsHolder.getProductDetails();
            final Optional<ProductDetail> optionalProductDetail = Objects.isNull(productDetails) ? Optional.empty() : productDetails.stream().findFirst();

            if (optionalProductDetail.isPresent()) {
                final ProductDetail productDetail = optionalProductDetail.get();
                final Long productId = productDetail.getProduct().id();
                final Collection<ProductDetail> existingProductDetails = Objects.nonNull(existingProductDetailsHolder)
                        ? existingProductDetailsHolder.getProductDetails() : null;

                if (Objects.nonNull(existingProductDetails) && !existingProductDetails.isEmpty()) {
                    existingProductDetailsHolder.getProductDetails().removeIf(linkedProductDetail -> Objects.equals(productId,
                            linkedProductDetail.getProduct().id()));
                    existingProductDetailsHolder.addProductDetail(productDetail);

                    productDetailsHolderManager.update(orgId, userId, existingProductDetailsHolder);
                } else {
                    productDetailsHolderManager.update(orgId, userId, productDetailsHolder);
                }

                response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.add.product.deal.success"));
            }
        } catch (Throwable throwable) {
            LOGGER.error("Zapier Action Execution: Failed to execute the add product to deal action. OrgId: {}, Reason: {}", orgId, throwable.getMessage());

            response.setErrorCode(ErrorCode.get(ZapierErrorCodes.UPDATE_ACTION_FAILED));
            response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.add.product.deal.failed"));
        } finally {
            response.send();
        }
    }
}

package com.tlc.crm.zapier.internal.action.dispatcher;

import com.tlc.commons.code.ErrorCode;
import com.tlc.commons.json.JsonObject;

import com.tlc.crm.common.action.CrmResponse;
import com.tlc.crm.common.converter.ConverterConfig;
import com.tlc.crm.common.models.Action;

import com.tlc.crm.core.api.deal.manager.DealManager;
import com.tlc.crm.core.api.deal.manager.ProductDetailsHolderManager;
import com.tlc.crm.core.api.deal.manager.PipelineStageManager;
import com.tlc.crm.core.api.deal.model.Deal.State;
import com.tlc.crm.core.api.deal.model.PipelineStage;
import com.tlc.crm.core.api.deal.model.Deal;
import com.tlc.crm.core.api.deal.model.ProductDetail;
import com.tlc.crm.core.api.deal.model.ProductDetailsHolder;
import com.tlc.crm.core.api.deal.model.converter.DealConverter;
import com.tlc.crm.core.api.deal.model.converter.ProductDetailsHolderConverter;
import com.tlc.crm.core.field.deal.DealFields;

import com.tlc.crm.entity.fields.source.Source;

import com.tlc.crm.zapier.api.models.ZapActionRequestContext;
import com.tlc.crm.zapier.fields.ZapAttributes;
import com.tlc.crm.zapier.internal.action.formatter.DealZapActionJsonFormatter;
import com.tlc.crm.zapier.internal.status.ZapierErrorCodes;

import com.tlc.validator.type.Group;

import java.util.Collection;
import java.util.Objects;
import java.util.Optional;

/**
 * Implementation of {@link DealZapActionDispatcher} for handling
 * Zapier actions related to deal entities.
 *
 * @author ThalaimalaiPandiyanT
 * @version 1.0
 */
public final class DealZapActionDispatcher extends AbstractSourceZapActionDispatcher {

    private final DealConverter dealConverter;
    private final DealManager dealManager;
    private final ProductDetailsHolderConverter productDetailsHolderConverter;
    private final ProductDetailsHolderManager productDetailsHolderManager;
    private final DealZapActionJsonFormatter dealZapActionJsonFormatter;

    private DealZapActionDispatcher() {
        this.dealConverter = DealConverter.getInstance();
        this.dealManager = DealManager.getInstance();
        this.productDetailsHolderConverter = ProductDetailsHolderConverter.getInstance();
        this.productDetailsHolderManager = ProductDetailsHolderManager.getInstance();
        this.dealZapActionJsonFormatter = DealZapActionJsonFormatter.getInstance();
    }

    private static final class Instance {
        private static final DealZapActionDispatcher ZAP_ACTION_DISPATCHER = new DealZapActionDispatcher();
    }

    public static DealZapActionDispatcher getInstance() {
        return Instance.ZAP_ACTION_DISPATCHER;
    }

    /**
     * {@inheritDoc}
     *
     * @param zapActionRequestContext The context containing the request, response, and action details.
     */
    @Override
    public void dispatch(final ZapActionRequestContext zapActionRequestContext) {
        switch (zapActionRequestContext.getZapAction()) {
            case CREATE_DEAL -> create(zapActionRequestContext);
            case UPDATE_DEAL -> update(zapActionRequestContext);
            case ADD_PRODUCT_TO_DEAL -> addProductToDeal(zapActionRequestContext);
        }
    }

    /**
     * Handles the creation logic for a Zapier action using the provided request context.
     *
     * @param zapActionRequestContext The context containing request data, metadata, and utilities needed to perform the action.
     */
    private void create(final ZapActionRequestContext zapActionRequestContext) {
        final Long orgId = zapActionRequestContext.getOrgId();
        final CrmResponse response = zapActionRequestContext.getResponse();
        final JsonObject dealJson = dealZapActionJsonFormatter.format(orgId, zapActionRequestContext.getZapAction(), zapActionRequestContext.getJsonObject());
        final Deal deal = dealConverter.convert(new ConverterConfig(orgId, zapActionRequestContext.getUserId(), null, false, dealJson), dealJson);
        final Collection<String> errors = validate(deal, Group.Create.class);

        if (errors.isEmpty()) {
            try {
                dealManager.create(deal);
                index(orgId, deal, Action.CREATE);

                response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.create.success"));
                response.send();
            } catch (Throwable throwable) {
                LOGGER.error("Zapier Action Execution: Failed to execute the deal create action. OrgId: {}, Reason: {}", orgId, throwable.getMessage());

                response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.create.failed"));
                response.setErrorCode(ErrorCode.get(ZapierErrorCodes.CREATE_ACTION_FAILED));
                response.send();
            }
        } else {
            response.setErrorCode(ErrorCode.get(ZapierErrorCodes.DATA_VALIDATION_FAILED));
            response.put(ZapAttributes.ERRORS, errors);
            response.send();
        }
    }

    /**
     * Performs an update operation for a Zapier action using the provided request context.
     *
     * @param zapActionRequestContext The context containing data and parameters required to update the target entity.
     */
    private void update(final ZapActionRequestContext zapActionRequestContext) {
        final Long orgId = zapActionRequestContext.getOrgId();
        final CrmResponse response = zapActionRequestContext.getResponse();
        final JsonObject dealJson = dealZapActionJsonFormatter.format(orgId, zapActionRequestContext.getZapAction(), zapActionRequestContext.getJsonObject());

        if (dealManager.exists(orgId, dealJson.getLong(ZapAttributes.ID))) {
            final Deal deal = dealConverter.convert(new ConverterConfig(orgId, zapActionRequestContext.getUserId(), null, true, dealJson), dealJson);
            final Collection<String> errors = validate(deal, Group.Update.class);

            if (errors.isEmpty()) {
                try {
                    setDealState(orgId, deal);
                    dealManager.update(deal);
                    index(orgId, deal, Action.UPDATE);

                    response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.update.success"));
                    response.send();
                } catch (Throwable throwable) {
                    LOGGER.error("Zapier Action Execution: Failed to execute the deal update action. OrgId: {}, Reason: {}", orgId, throwable.getMessage());

                    response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.deal.update.failed"));
                    response.setErrorCode(ErrorCode.get(ZapierErrorCodes.UPDATE_ACTION_FAILED));
                    response.send();
                }
            } else {
                response.setErrorCode(ErrorCode.get(ZapierErrorCodes.DATA_VALIDATION_FAILED));
                response.put(ZapAttributes.ERRORS, errors);
                response.send();
            }
        } else {
            response.setErrorCode(ErrorCode.get(ZapierErrorCodes.ENTITY_NOT_FOUND));
            response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.entity.invalid"));
            response.send();
        }
    }

    /**
     * Sets the state of the given deal for the specified organization.
     *
     * @param orgId The ID of the organization to which the deal belongs.
     * @param deal  The {@link Deal} object whose state is to be updated.
     */
    private void setDealState(final Long orgId, final Deal deal) {
        final PipelineStage pipelineStage = deal.getPipelineStage();

        if (Objects.nonNull(pipelineStage)) {
            final String pipelineStageName = PipelineStageManager.getInstance().get(orgId, pipelineStage.id()).getName();

            if (Objects.nonNull(pipelineStageName)) {
                deal.setState(Deal.State.getStateByName(pipelineStageName));
            }
            final State state = deal.getState();

            switch (state) {
                case WON -> {
                    if (Objects.isNull(deal.getWonReason())) {
                        fieldService.getDefaultFieldByAliasName(Source.DEAL, DealFields.WON_REASON)
                                .ifPresent(fieldInfo -> optionService.get(orgId, fieldInfo).stream().findFirst().ifPresent(deal::setWonReason));
                    }
                }
                case LOST -> {
                    if (Objects.isNull(deal.getLostReason())) {
                        fieldService.getDefaultFieldByAliasName(Source.DEAL, DealFields.LOST_REASON)
                                .ifPresent(fieldInfo -> optionService.get(orgId, fieldInfo).stream().findFirst().ifPresent(deal::setLostReason));
                    }
                }
            }
        }
    }

    /**
     * Adds a product to an existing deal using the provided Zapier action context.
     *
     * @param zapActionRequestContext The context containing deal and product data required to perform the operation.
     */
    private void addProductToDeal(final ZapActionRequestContext zapActionRequestContext) {
        final Long orgId = zapActionRequestContext.getOrgId();
        final Long userId = zapActionRequestContext.getUserId();
        final CrmResponse response = zapActionRequestContext.getResponse();

        try {
            final JsonObject productDetailsJson = dealZapActionJsonFormatter.formatAddProductJson(orgId, zapActionRequestContext.getZapAction(), zapActionRequestContext.getJsonObject());
            final ProductDetailsHolder existingProductDetailsHolder = productDetailsHolderManager.getLinkedProductList(orgId, productDetailsJson.getLong(ZapAttributes.DEAL_ID), false);
            final ProductDetailsHolder productDetailsHolder = productDetailsHolderConverter.convert(new ConverterConfig(orgId, userId, null, false, productDetailsJson), productDetailsJson);
            final Collection<ProductDetail> productDetails = productDetailsHolder.getProductDetails();
            final Optional<ProductDetail> optionalProductDetail = Objects.isNull(productDetails) ? Optional.empty() : productDetails.stream().findFirst();

            if (optionalProductDetail.isPresent()) {
                final ProductDetail productDetail = optionalProductDetail.get();
                final Long productId = productDetail.getProduct().id();
                final Collection<ProductDetail> existingProductDetails = Objects.nonNull(existingProductDetailsHolder)
                        ? existingProductDetailsHolder.getProductDetails() : null;

                if (Objects.nonNull(existingProductDetails) && !existingProductDetails.isEmpty()) {
                    existingProductDetailsHolder.getProductDetails().removeIf(linkedProductDetail -> Objects.equals(productId,
                            linkedProductDetail.getProduct().id()));
                    existingProductDetailsHolder.addProductDetail(productDetail);

                    productDetailsHolderManager.update(orgId, userId, existingProductDetailsHolder);
                } else {
                    productDetailsHolderManager.update(orgId, userId, productDetailsHolder);
                }

                response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.add.product.deal.success"));
            }
        } catch (Throwable throwable) {
            LOGGER.error("Zapier Action Execution: Failed to execute the add product to deal action. OrgId: {}, Reason: {}", orgId, throwable.getMessage());

            response.setErrorCode(ErrorCode.get(ZapierErrorCodes.UPDATE_ACTION_FAILED));
            response.put(ZapAttributes.MESSAGE, response.resolveI18nString("i18n.crm.zapier.action.add.product.deal.failed"));
        } finally {
            response.send();
        }
    }
}

package com.tlc.resilience.ratelimit.resolver;

import com.tlc.resilience.ratelimit.RateLimitContext;
import com.tlc.resilience.ratelimit.RateLimitScope;

import java.util.Objects;

/**
 * <p>
 * Default implementation of {@link RateLimitKeyResolver} that constructs
 * rate limit keys based on the {@link RateLimitScope}.
 * </p>
 *
 * <p>Key formats by scope:</p>
 * <ul>
 *     <li>{@code GLOBAL} — {@code global:<path>}</li>
 *     <li>{@code PER_IP} — {@code ip:<ip>:<path>}</li>
 *     <li>{@code PER_ORG} — {@code org:<orgId>:<path>}</li>
 *     <li>{@code PER_USER_IN_ORG} — {@code user:<orgId>:<userId>:<path>}</li>
 *     <li>{@code CUSTOM} — {@code custom:<customKey>:<path>} (requires custom key in context)</li>
 * </ul>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public final class DefaultRateLimitKeyResolver implements RateLimitKeyResolver {

    private static final DefaultRateLimitKeyResolver INSTANCE = new DefaultRateLimitKeyResolver();

    private DefaultRateLimitKeyResolver() {
    }

    /**
     * Returns the singleton instance.
     *
     * @return The default key resolver instance.
     */
    public static DefaultRateLimitKeyResolver getInstance() {
        return INSTANCE;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String resolve(final RateLimitScope scope, final RateLimitContext context) {
        Objects.requireNonNull(scope, "Rate limit scope must not be null");
        Objects.requireNonNull(context, "Rate limit context must not be null");

        final String path = Objects.requireNonNullElse(context.getPath(), "unknown");

        return switch (scope) {
            case GLOBAL -> String.format("global:%s", path);
            case PER_IP -> String.format("ip:%s:%s", Objects.requireNonNullElse(context.getIp(), "unknown"), path);
            case PER_ORG -> String.format("org:%s:%s", context.getOrgId(), path);
            case PER_USER_IN_ORG -> String.format("user:%s:%s:%s", context.getOrgId(), context.getUserId(), path);
        };
    }
}

