package com.tlc.resilience.ratelimit.distributed;

import com.tlc.cache.Cache;
import com.tlc.cache.remote.CacheConfig;
import com.tlc.cache.service.provider.CacheServiceProvider;

import com.tlc.resilience.ratelimit.RateLimitResult;
import com.tlc.resilience.ratelimit.RateLimitType;
import com.tlc.resilience.ratelimit.RateLimiter;

import java.io.Serializable;

/**
 * <p>
 * Distributed token bucket rate limiter using the cache service.
 * Tokens are replenished at a fixed rate and each request consumes one token.
 * All application instances share the same bucket state via a distributed cache.
 * </p>
 *
 * <p>Bucket state (available tokens and last refill timestamp) is stored as a
 * {@link BucketState} object in a shared cache keyed per rate limit key.</p>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public final class DistributedTokenBucketRateLimiter implements RateLimiter {

    private final int maxTokens;
    private final int windowInSeconds;
    private final double refillRatePerMillis;
    private final Cache<String, BucketState> bucketCache;

    /**
     * Constructs a {@code DistributedTokenBucketRateLimiter}.
     *
     * @param maxTokens       The maximum number of tokens (burst capacity).
     * @param windowInSeconds The time window in seconds to fully refill the bucket.
     */
    public DistributedTokenBucketRateLimiter(final int maxTokens, final int windowInSeconds) {
        this.maxTokens = maxTokens;
        this.windowInSeconds = windowInSeconds;
        this.refillRatePerMillis = (double) maxTokens / (windowInSeconds * 1000L);

        final CacheConfig<String, BucketState> cacheConfig = new CacheConfig<>("token_bucket_rate_limiter");

        cacheConfig.setTtl(windowInSeconds * 2 * 1000);
        this.bucketCache = CacheServiceProvider.get().createOrOpenCache(cacheConfig);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean tryAcquire(final String key) {
        return tryAcquireWithResult(key).isAllowed();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public synchronized RateLimitResult tryAcquireWithResult(final String key) {
        final String bucketKey = "rl:tb:" + key;
        final long now = System.currentTimeMillis();

        BucketState state = bucketCache.get(bucketKey);

        if (state == null) {
            state = new BucketState((long) maxTokens * 1000, now);
        }

        final long elapsed = now - state.getLastRefillMillis();
        final long tokensToAdd = (long) (elapsed * refillRatePerMillis * 1000);
        long tokensX1000 = Math.min((long) maxTokens * 1000, state.getTokens() + tokensToAdd);

        state.setLastRefillMillis(now);

        final boolean allowed;

        if (tokensX1000 >= 1000) {
            tokensX1000 -= 1000;
            allowed = true;
        } else {
            allowed = false;
        }

        state.setTokens(tokensX1000);
        bucketCache.put(bucketKey, state);

        final int remaining = Math.max(0, (int) (tokensX1000 / 1000));
        final long resetTimeInSeconds = (now / 1000) + windowInSeconds;

        return new RateLimitResult(allowed, remaining, resetTimeInSeconds, maxTokens);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public RateLimitType getType() {
        return RateLimitType.TOKEN_BUCKET;
    }

    private static final class BucketState implements Serializable {

        private long tokens;
        private long lastRefillMillis;

        /**
         * Constructs a {@code BucketState} with the given initial values.
         *
         * @param tokens           The available tokens scaled by 1000 for precision.
         * @param lastRefillMillis The last refill timestamp in milliseconds.
         */
        BucketState(final long tokens, final long lastRefillMillis) {
            this.tokens = tokens;
            this.lastRefillMillis = lastRefillMillis;
        }

        long getTokens() {
            return tokens;
        }

        void setTokens(final long tokens) {
            this.tokens = tokens;
        }

        long getLastRefillMillis() {
            return lastRefillMillis;
        }

        void setLastRefillMillis(final long lastRefillMillis) {
            this.lastRefillMillis = lastRefillMillis;
        }
    }
}

package com.tlc.resilience.ratelimit.distributed;

import com.tlc.cache.Cache;
import com.tlc.cache.remote.CacheConfig;
import com.tlc.cache.service.provider.CacheServiceProvider;

import com.tlc.resilience.ratelimit.RateLimitResult;
import com.tlc.resilience.ratelimit.RateLimitType;
import com.tlc.resilience.ratelimit.RateLimiter;

import java.io.Serializable;

/**
 * <p>
 * Distributed token bucket rate limiter using the cache service.
 * Tokens are replenished at a fixed rate and each request consumes one token.
 * All application instances share the same bucket state via a distributed cache.
 * </p>
 *
 * <p>Bucket state (available tokens and last refill timestamp) is stored as a
 * {@link BucketState} object in a shared cache keyed per rate limit key.</p>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public final class DistributedTokenBucketRateLimiter implements RateLimiter {

    private final int maxTokens;
    private final int windowInSeconds;
    private final double refillRatePerMillis;
    private final Cache<String, BucketState> bucketCache;

    /**
     * Constructs a {@code DistributedTokenBucketRateLimiter}.
     *
     * @param maxTokens       The maximum number of tokens (burst capacity).
     * @param windowInSeconds The time window in seconds to fully refill the bucket.
     */
    public DistributedTokenBucketRateLimiter(final int maxTokens, final int windowInSeconds) {
        this.maxTokens = maxTokens;
        this.windowInSeconds = windowInSeconds;
        this.refillRatePerMillis = (double) maxTokens / (windowInSeconds * 1000L);

        final CacheConfig<String, BucketState> cacheConfig = new CacheConfig<>("token_bucket_rate_limiter");

        cacheConfig.setTtl(windowInSeconds * 2 * 1000);
        this.bucketCache = CacheServiceProvider.get().createOrOpenCache(cacheConfig);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean tryAcquire(final String key) {
        return tryAcquireWithResult(key).isAllowed();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public RateLimitResult tryAcquireWithResult(final String key) {
        final String bucketKey = "rl:tb:" + key;
        final long now = System.currentTimeMillis();
        final boolean[] allowed = {false};

        // Single atomic compute: the read-modify-write is one Redis EVAL round trip.
        // No 'synchronized' needed – the cache layer guarantees atomicity across all nodes.
        final BucketState newState = bucketCache.compute(bucketKey, oldState -> {
            final long tokensX1000Before;

            if (oldState == null) {
                tokensX1000Before = (long) maxTokens * 1000;
            } else {
                final long elapsed = now - oldState.getLastRefillMillis();
                final long tokensToAdd = (long) (elapsed * refillRatePerMillis * 1000);
                tokensX1000Before = Math.min((long) maxTokens * 1000, oldState.getTokens() + tokensToAdd);
            }

            final long tokensX1000After;

            if (tokensX1000Before >= 1000) {
                tokensX1000After = tokensX1000Before - 1000;
                allowed[0] = true;
            } else {
                tokensX1000After = tokensX1000Before;
            }

            return new BucketState(tokensX1000After, now);
        });

        final int remaining = Math.max(0, (int) (newState.getTokens() / 1000));
        final long resetTimeInSeconds = (now / 1000) + windowInSeconds;

        return new RateLimitResult(allowed[0], remaining, resetTimeInSeconds, maxTokens);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public RateLimitType getType() {
        return RateLimitType.TOKEN_BUCKET;
    }

    private static final class BucketState implements Serializable {

        private long tokens;
        private long lastRefillMillis;

        /**
         * Constructs a {@code BucketState} with the given initial values.
         *
         * @param tokens           The available tokens scaled by 1000 for precision.
         * @param lastRefillMillis The last refill timestamp in milliseconds.
         */
        BucketState(final long tokens, final long lastRefillMillis) {
            this.tokens = tokens;
            this.lastRefillMillis = lastRefillMillis;
        }

        long getTokens() {
            return tokens;
        }

        void setTokens(final long tokens) {
            this.tokens = tokens;
        }

        long getLastRefillMillis() {
            return lastRefillMillis;
        }

        void setLastRefillMillis(final long lastRefillMillis) {
            this.lastRefillMillis = lastRefillMillis;
        }
    }
}

package com.tlc.crm.core.conversation.action;

import com.tlc.commons.code.ErrorCode;
import com.tlc.commons.json.JsonObject;

import com.tlc.crm.common.action.CrmRequest;
import com.tlc.crm.common.action.CrmResponse;
