            assertEquals(-1, hikariConfig.getMinimumIdle());
        }

        @Test
        @DisplayName("Should use HikariCP default idleTimeout (600000) when connectionPool.idle.timeout is not set")
        void shouldUseDefaultIdleTimeout() {
            final HikariConfig hikariConfig = PgsqlService.buildHikariConfig(pgDataSource, new Configurations(new HashMap<>()));

            assertEquals(600000, hikariConfig.getIdleTimeout());
        }
    }

