package com.tlc.resilience.ratelimit.adapter;

import com.tlc.resilience.ratelimit.RateLimitConfig;
import com.tlc.resilience.ratelimit.RateLimitContext;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * <p>
 * Registry for managing {@link RateLimitConfigAdapter} instances.
 * Allows registration of custom adapters for different rate limit categories
 * and provides methods to resolve configurations dynamically.
 * </p>
 *
 * <p>This registry supports:</p>
 * <ul>
 *     <li>Category-specific adapters (one per category key)</li>
 *     <li>Global/fallback adapters (evaluated in priority order)</li>
 *     <li>Type-safe configuration resolution using generics</li>
 * </ul>
 *
 * <p>Usage example:</p>
 * <pre>
 * // Register adapters at application startup
 * RateLimitConfigAdapterRegistry.register(myWebAdapter);
 * RateLimitConfigAdapterRegistry.register(myPlanAdapter);
 *
 * // Resolve configuration at runtime
 * RateLimitConfig config = RateLimitConfigAdapterRegistry.resolve("WEB_REQUEST", context);
 * </pre>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public final class RateLimitConfigAdapterRegistry {

    private static final Map<Object, RateLimitConfigAdapter<?, ?>> ADAPTERS = new ConcurrentHashMap<>();
    private static final List<RateLimitConfigAdapter<?, ?>> GLOBAL_ADAPTERS = new CopyOnWriteArrayList<>();
    private static final RateLimitConfig DEFAULT_CONFIG = new RateLimitConfig();

    private RateLimitConfigAdapterRegistry() {
    }

    /**
     * Registers a category-specific adapter. Replaces any existing adapter for the same category.
     *
     * @param adapter The adapter to register.
     * @param <C>     The configuration type.
     * @param <K>     The category key type.
     * @throws NullPointerException if adapter or its category is null.
     */
    public static <C extends RateLimitConfig, K> void register(final RateLimitConfigAdapter<C, K> adapter) {
        Objects.requireNonNull(adapter, "Adapter must not be null");
        Objects.requireNonNull(adapter.getCategory(), "Adapter category must not be null");

        final RateLimitConfigAdapter<?, ?> existing = ADAPTERS.put(adapter.getCategory(), adapter);

        if (Objects.nonNull(existing)) {
            existing.onUnregister();
        }

        adapter.onRegister();
    }

    /**
     * Registers a global/fallback adapter that applies when no category-specific adapter is found.
     * Global adapters are evaluated in order of priority (highest first).
     *
     * @param adapter The global adapter to register.
     * @param <C>     The configuration type.
     * @param <K>     The category key type.
     */
    public static <C extends RateLimitConfig, K> void registerGlobal(final RateLimitConfigAdapter<C, K> adapter) {
        Objects.requireNonNull(adapter, "Adapter must not be null");

        GLOBAL_ADAPTERS.add(adapter);
        GLOBAL_ADAPTERS.sort((a, b) -> Integer.compare(b.getPriority(), a.getPriority()));
        adapter.onRegister();
    }

    /**
     * Unregisters the adapter for the given category.
     *
     * @param category The category key to unregister.
     * @param <K>      The category key type.
     * @return The removed adapter, or {@code null} if none was registered.
     */
    @SuppressWarnings("unchecked")
    public static <K> RateLimitConfigAdapter<?, K> unregister(final K category) {
        final RateLimitConfigAdapter<?, ?> removed = ADAPTERS.remove(category);

        if (Objects.nonNull(removed)) {
            removed.onUnregister();
        }

        return (RateLimitConfigAdapter<?, K>) removed;
    }

    /**
     * Unregisters a global adapter.
     *
     * @param adapter The adapter to remove.
     * @return {@code true} if the adapter was removed.
     */
    public static boolean unregisterGlobal(final RateLimitConfigAdapter<?, ?> adapter) {
        final boolean removed = GLOBAL_ADAPTERS.remove(adapter);

        if (removed) {
            adapter.onUnregister();
        }

        return removed;
    }

    /**
     * Returns the adapter registered for the given category.
     *
     * @param category The category key.
     * @param <C>      The configuration type.
     * @param <K>      The category key type.
     * @return An {@link Optional} containing the adapter, or empty if none registered.
     */
    @SuppressWarnings("unchecked")
    public static <C extends RateLimitConfig, K> Optional<RateLimitConfigAdapter<C, K>> getAdapter(final K category) {
        return Optional.ofNullable((RateLimitConfigAdapter<C, K>) ADAPTERS.get(category));
    }

    /**
     * Checks if an adapter is registered for the given category.
     *
     * @param category The category key.
     * @return {@code true} if an adapter is registered.
     */
    public static boolean hasAdapter(final Object category) {
        return ADAPTERS.containsKey(category);
    }

    /**
     * Resolves the rate limit configuration for the given category and context.
     * Falls back to global adapters, then to the default config if no adapter is found.
     *
     * @param category The category key.
     * @param context  The rate limit context.
     * @param <K>      The category key type.
     * @return The resolved {@link RateLimitConfig}.
     */
    @SuppressWarnings("unchecked")
    public static <K> RateLimitConfig resolve(final K category, final RateLimitContext context) {
        Objects.requireNonNull(category, "Category must not be null");
        Objects.requireNonNull(context, "Context must not be null");

        // Try category-specific adapter first
        final RateLimitConfigAdapter<RateLimitConfig, K> categoryAdapter =
                (RateLimitConfigAdapter<RateLimitConfig, K>) ADAPTERS.get(category);

        if (Objects.nonNull(categoryAdapter)) {
            final RateLimitConfig config = categoryAdapter.resolve(context);

            if (Objects.nonNull(config)) {
                return config;
            }

            // Fall back to adapter's default
            final RateLimitConfig defaultConfig = categoryAdapter.getDefaultConfig();

            if (Objects.nonNull(defaultConfig)) {
                return defaultConfig;
            }
        }

        // Fall back to global adapters
        for (final RateLimitConfigAdapter<?, ?> globalAdapter : GLOBAL_ADAPTERS) {
            final RateLimitConfig config = ((RateLimitConfigAdapter<RateLimitConfig, ?>) globalAdapter).resolve(context);

            if (Objects.nonNull(config)) {
                return config;
            }
        }

        // Return default config
        return DEFAULT_CONFIG;
    }

    /**
     * Resolves using the adapter registered for the context's category attribute.
     *
     * @param context The rate limit context (must have category attribute set).
     * @return The resolved {@link RateLimitConfig}.
     */
    public static RateLimitConfig resolve(final RateLimitContext context) {
        Objects.requireNonNull(context, "Context must not be null");

        final Object category = context.getAttribute("category");

        if (Objects.nonNull(category)) {
            return resolve(category, context);
        }

        // No category - use global adapters or default
        for (final RateLimitConfigAdapter<?, ?> globalAdapter : GLOBAL_ADAPTERS) {
            @SuppressWarnings("unchecked")
            final RateLimitConfig config = ((RateLimitConfigAdapter<RateLimitConfig, ?>) globalAdapter).resolve(context);

            if (Objects.nonNull(config)) {
                return config;
            }
        }

        return DEFAULT_CONFIG;
    }

    /**
     * Returns the default configuration used when no adapter matches.
     *
     * @return The default {@link RateLimitConfig}.
     */
    public static RateLimitConfig getDefaultConfig() {
        return DEFAULT_CONFIG;
    }

    /**
     * Clears all registered adapters. Use with caution — primarily for testing.
     */
    public static void clearAll() {
        ADAPTERS.values().forEach(RateLimitConfigAdapter::onUnregister);
        GLOBAL_ADAPTERS.forEach(RateLimitConfigAdapter::onUnregister);
        ADAPTERS.clear();
        GLOBAL_ADAPTERS.clear();
    }

    /**
     * Returns the number of category-specific adapters registered.
     *
     * @return The count of registered adapters.
     */
    public static int size() {
        return ADAPTERS.size();
    }

    /**
     * Returns the number of global adapters registered.
     *
     * @return The count of global adapters.
     */
    public static int globalSize() {
        return GLOBAL_ADAPTERS.size();
    }
}

package com.tlc.resilience.ratelimit;

/**
 * <p>
 * Holds the contextual information needed to resolve a rate limit key.
 * This is passed to the {@code RateLimitKeyResolver} to construct the
 * appropriate key based on the configured {@code RateLimitScope}.
 * </p>
 *
 * <p>
 * For custom rate limiting strategies (e.g., plan/subscription-based),
 * use the {@code customKey} field to provide a custom identifier.
 * </p>
 *
 * @author Thalaimalai Pandiyan T
 * @version 1.0
 */
public final class RateLimitContext {

    private final String path;
    private final String ip;
    private final Long orgId;
    private final Long userId;
    private final String customKey;

    private RateLimitContext(final Builder builder) {
        this.path = builder.path;
        this.ip = builder.ip;
        this.orgId = builder.orgId;
        this.userId = builder.userId;
        this.customKey = builder.customKey;
    }

    /**
     * Returns the request path or endpoint identifier.
     *
     * @return The path.
     */
    public String getPath() {
        return path;
    }

    /**
     * Returns the client IP address.
     *
     * @return The IP address, or {@code null} if not available.
     */
    public String getIp() {
        return ip;
    }

    /**
     * Returns the organization ID.
     *
     * @return The org ID, or {@code null} if not available.
     */
    public Long getOrgId() {
        return orgId;
    }

    /**
     * Returns the user ID.
     *
     * @return The user ID, or {@code null} if not available.
     */
    public Long getUserId() {
        return userId;
    }

    /**
     * Returns the custom key for custom rate limiting strategies.
     * This can be used for plan/subscription-based rate limiting
     * or any other custom key resolution logic.
     *
     * @return The custom key, or {@code null} if not set.
     */
    public String getCustomKey() {
        return customKey;
    }

    /**
     * Creates a new {@code Builder} instance.
     *
     * @return A new builder.
     */
    public static Builder builder() {
        return new Builder();
    }

    /**
     * Builder for {@code RateLimitContext}.
     */
    public static final class Builder {

        private String path;
        private String ip;
        private Long orgId;
        private Long userId;
        private String customKey;

        private Builder() {
        }

        public Builder path(final String path) {
            this.path = path;
            return this;
        }

        public Builder ip(final String ip) {
            this.ip = ip;
            return this;
        }

        public Builder orgId(final Long orgId) {
            this.orgId = orgId;
            return this;
        }

        public Builder userId(final Long userId) {
            this.userId = userId;
            return this;
        }

        public RateLimitContext build() {
            return new RateLimitContext(this);
        }
    }
}

