import com.tlc.notification.internal.twilio.TwilioSmsService;
import com.tlc.notification.internal.twilio.TwilioVoiceCallService;
import com.tlc.notification.internal.twilio.TwilioWhatsappService;
import com.tlc.notification.key.NotificationKeys;
import com.tlc.notification.service.PushNotificationService;
import com.tlc.notification.service.provider.SmsServiceProvider;
import com.tlc.notification.service.provider.VoiceCallServiceProvider;
import com.tlc.notification.service.provider.WhatsappServiceProvider;

/**
 * <p>
 * Provides the instance of third party services.
 * </p>
 *
 * @author Sathish
 * @version 1.0
 */
class ExternalServiceInstanceProvider {

    /**
     * <p>
     * Provides the {@link VoiceCallServiceProvider} object.
     * </p>
     *
     * @param configurations properties for create the service provider object
     * @return {@link VoiceCallServiceProvider} object
     */
    static VoiceCallServiceProvider getVoiceCallService(final Configurations configurations) {
        final Configurations callConfig = configurations.getNestedConfigs(NotificationKeys.TWILIO.getKey());

        return callConfig.getFirstKey().isPresent() ? TwilioVoiceCallService.getInstance(callConfig) : null; //TODO when changing external service provider for voice call
    }

    /**
     * <p>
     * Provides the {@link SmsServiceProvider} object.
     * </p>
     *
     * @param configurations properties for create the service provider object
     * @return {@link SmsServiceProvider} object
     */
    static SmsServiceProvider getSMSService(final Configurations configurations) {
        final Configurations callConfig = configurations.getNestedConfigs(NotificationKeys.TWILIO.getKey());

        return callConfig.getFirstKey().isPresent() ? TwilioSmsService.getInstance(callConfig) : null;  //TODO when changing external service provider for SMS
    }

    /**
     * <p>
     * Provides the {@link WhatsappServiceProvider} object.
     * </p>
     *
     * @param configurations properties for create the service provider object
     * @return {@link WhatsappServiceProvider} object
     */
    static WhatsappServiceProvider getWhatsappService(final Configurations configurations) {
        final Configurations callConfig = configurations.getNestedConfigs(NotificationKeys.TWILIO.getKey());

        return callConfig.getFirstKey().isPresent() ? TwilioWhatsappService.getInstance(callConfig) : null;  //TODO while changing external service provider for whatsapp
    }

    /**
     * <p>
     * Creates the {@link PushNotificationService} based on the configured service key.
     * The returned instance directly implements the service interfaces — no intermediate provider layer.
     * Currently supports Azure Web PubSub. Future services (FCM, native WebSocket, etc.) can be added here.
     * </p>
     *
     * @param configurations properties for creating the push notification service
     * @return {@link PushNotificationService} instance, or null if not configured
     */
    static PushNotificationService<?> getPushNotificationService(final Configurations configurations) {
        final Configurations pushConfig = configurations.getNestedConfigs(NotificationKeys.PUSH_NOTIFICATION.getKey());

        if (pushConfig.isEmpty()) {
            return null;
        }
        final String serviceKey = pushConfig.optConfig(NotificationKeys.PUSH_NOTIFICATION_PROVIDER.getKey(), NotificationKeys.AZURE_WEBPUBSUB.getKey());

        if (NotificationKeys.AZURE_WEBPUBSUB.getKey().equals(serviceKey)) {
            final Configurations azureConfig = pushConfig.getNestedConfigs(NotificationKeys.AZURE_WEBPUBSUB.getKey());

            return new AzureWebPubSubService(new AzureWebPubSubConfig(azureConfig));
        }
        return null; //TODO add more services (FCM, native WebSocket, etc.) here
    }
}

package com.tlc.notification.internal.impl;

import com.tlc.commons.util.ConfHolder;
import com.tlc.commons.util.Configurations;

import com.tlc.notification.internal.calendar.GoogleCalendarService;
import com.tlc.notification.internal.config.PushNotificationServiceImpl;
import com.tlc.notification.internal.config.SmsServiceImpl;
import com.tlc.notification.internal.config.VoiceCallServiceImpl;
import com.tlc.notification.internal.config.WhatsappServiceImpl;
import com.tlc.notification.internal.contact.GoogleContactService;
import com.tlc.notification.key.NotificationKeys;
import com.tlc.notification.service.NotificationService;
import com.tlc.notification.service.PushNotificationService;
import com.tlc.notification.service.notification.SmsService;
import com.tlc.notification.service.notification.VoiceCallService;
import com.tlc.notification.service.notification.WhatsappService;
import com.tlc.notification.service.provider.PushNotificationProvider;
import com.tlc.notification.service.telephony.mcube.MCubeService;
import com.tlc.notification.service.telephony.telecmi.TeleCMIService;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * <p>
 * Provides the services of the notification.
 * </p>
 *
 * @author Sathish
 * @version 1.0
 */
public class NotificationsServiceImpl implements NotificationService {

    private static final Logger LOGGER = LoggerFactory.getLogger(NotificationsServiceImpl.class);

    private final Configurations emailAppConfigs;

    private VoiceCallService voiceCallService;
    private SmsService smsService;
    private WhatsappService whatsappService;
    private PushNotificationService pushNotificationService;

    private final TeleCMIService teleCMIService;
    private final MCubeService mcubeService;

    public NotificationsServiceImpl() {
        this.emailAppConfigs = ConfHolder.getInstance().getProperties(NotificationKeys.SYNC_SERVICE.getKey());

        teleCMIService =  TeleCMIService.getInstance();
        mcubeService =  MCubeService.getInstance();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void start(final Configurations configurations) {
        this.voiceCallService = new VoiceCallServiceImpl(ExternalServiceInstanceProvider.getVoiceCallService(configurations));
        this.smsService = new SmsServiceImpl(ExternalServiceInstanceProvider.getSMSService(configurations));
        this.whatsappService = new WhatsappServiceImpl(ExternalServiceInstanceProvider.getWhatsappService(configurations));

        /* Push Notification */
        final PushNotificationProvider pushProvider = ExternalServiceInstanceProvider.getPushNotificationProvider(configurations);

        if (pushProvider != null) {
            this.pushNotificationService = new PushNotificationServiceImpl(pushProvider);
        }

        /* Calendar */
        GoogleCalendarService.getInstance().setAppProperties(emailAppConfigs);

        /* Contact */
        GoogleContactService.getInstance().setAppProperties(emailAppConfigs);

        teleCMIService.start(configurations);
        mcubeService.start(configurations);

        LOGGER.info("Notification Service Activated");
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void stop() {
        voiceCallService.stop();
        smsService.stop();
        whatsappService.stop();

        if (pushNotificationService != null) {
            pushNotificationService.stop();
        }

        teleCMIService.stop();
        mcubeService.stop();
        LOGGER.info("Notification Service Deactivated");
    }

    /**
     * {@inheritDoc}
     *
     * @return {@link VoiceCallService}
     */
    @Override
    public VoiceCallService getVoiceCallService() {
        return voiceCallService;
    }

    /**
     * {@inheritDoc}
     *
     * @return {@link SmsService}
     */
    @Override
    public SmsService getSmsService() {
        return smsService;
    }

    /**
     * {@inheritDoc}
     *
     * @return {@link WhatsappService}
     */
    @Override
    public WhatsappService getWhatsappService() {
        return whatsappService;
    }

    /**
     * {@inheritDoc}
     *
     * @return {@link PushNotificationService}
     */
    @Override
    public PushNotificationService pushNotificationService() {
        return pushNotificationService;
    }
}

