package com.tlc.notification.internal.pubsub;

import com.azure.messaging.webpubsub.WebPubSubServiceClient;
import com.azure.messaging.webpubsub.WebPubSubServiceClientBuilder;
import com.azure.messaging.webpubsub.models.GetClientAccessTokenOptions;
import com.azure.messaging.webpubsub.models.WebPubSubClientAccessToken;
import com.azure.messaging.webpubsub.models.WebPubSubContentType;
import com.tlc.commons.code.ErrorCode;
import com.tlc.commons.code.ErrorCodes;
import com.tlc.notification.service.PushAccessService;
import com.tlc.notification.service.PushManagementService;
import com.tlc.notification.service.push.ClientAccessRequest;
import com.tlc.notification.service.push.ConnectionRequest;
import com.tlc.notification.service.push.PushGroupRequest;
import com.tlc.notification.service.push.PushRequest;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * <p>
 * Azure Web PubSub implementation of push notification services.
 * Implements all segregated service interfaces since Azure Web PubSub supports
 * messaging, group management, connection management, and client access tokens.
 * </p>
 *
 * <p>Service-specific options consumed from request objects:</p>
 * <ul>
 *   <li><b>contentType</b> (String) - "application/json" (default) or "text/plain"</li>
 *   <li><b>tokenLifetimeInMinutes</b> (Integer) - for client access token TTL</li>
 * </ul>
 *
 * @version 1.0
 */
public class AzureWebPubSubService implements PushManagementService, PushAccessService {

    private static final Logger LOGGER = LoggerFactory.getLogger(AzureWebPubSubService.class);

    private WebPubSubServiceClient serviceClient;

    public AzureWebPubSubService(final AzureWebPubSubConfig config) {
        this.serviceClient = new WebPubSubServiceClientBuilder()
                .connectionString(config.getConnectionString())
                .hub(config.getHubName())
                .buildClient();
        LOGGER.info("Azure Web PubSub service initialized for hub: {}", config.getHubName());
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public <T> void send(final PushRequest<T> request) {
        final String payload = String.valueOf(request.getPayload());
        final String contentTypeStr = request.getOption("contentType", String.class);
        final WebPubSubContentType contentType = resolveContentType(contentTypeStr != null ? contentTypeStr : "application/json");

        try {
            switch (request.getTargetType()) {
                case CONNECTION:
                    serviceClient.sendToConnection(request.getTargetId(), payload, contentType);
                    break;
                case USER:
                    serviceClient.sendToUser(request.getTargetId(), payload, contentType);
                    break;
                case GROUP:
                    serviceClient.sendToGroup(request.getTargetId(), payload, contentType);
                    break;
                case ALL:
                    serviceClient.sendToAll(payload, contentType);
                    break;
                default:
                    throw ErrorCode.get(ErrorCodes.INVALID_DATA);
            }
        } catch (ErrorCode errorCode) {
            throw errorCode;
        } catch (Exception exception) {
            LOGGER.error("Failed to send push message [targetType={}, targetId={}]",
                    request.getTargetType(), request.getTargetId(), exception);
            throw ErrorCode.get(ErrorCodes.UNKNOWN_ERROR, exception);
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void manageGroup(final PushGroupRequest request) {
        final String group = request.getGroup();
        final String targetId = request.getTargetId();

        try {
            switch (request.getAction()) {
                case ADD_CONNECTION:
                    serviceClient.addConnectionToGroupWithResponse(group, targetId, null);
                    break;
                case REMOVE_CONNECTION:
                    serviceClient.removeConnectionFromGroupWithResponse(group, targetId, null);
                    break;
                case ADD_USER:
                    serviceClient.addUserToGroupWithResponse(group, targetId, null);
                    break;
                case REMOVE_USER:
                    serviceClient.removeUserFromGroupWithResponse(group, targetId, null);
                    break;
                default:
                    throw ErrorCode.get(ErrorCodes.INVALID_DATA);
            }
        } catch (ErrorCode errorCode) {
            throw errorCode;
        } catch (Exception exception) {
            LOGGER.error("Failed to manage group [action={}, group={}, targetId={}]",
                    request.getAction(), group, targetId, exception);
            throw ErrorCode.get(ErrorCodes.UNKNOWN_ERROR, exception);
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String generateClientAccess(final ClientAccessRequest request) {
        try {
            final GetClientAccessTokenOptions options = new GetClientAccessTokenOptions()
                    .setUserId(request.getUserId());

            request.getRoles().forEach(options::addRole);

            final Integer tokenLifetime = request.getOption("tokenLifetimeInMinutes", Integer.class);

            if (tokenLifetime != null) {
                options.setExpiresAfter(java.time.Duration.ofMinutes(tokenLifetime));
            }

            final WebPubSubClientAccessToken token = serviceClient.getClientAccessToken(options);

            return token.getUrl();
        } catch (Exception exception) {
            LOGGER.error("Failed to generate client access URL for user: {}", request.getUserId(), exception);
            throw ErrorCode.get(ErrorCodes.UNKNOWN_ERROR, exception);
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean manageConnection(final ConnectionRequest request) {
        final String connectionId = request.getConnectionId();

        try {
            switch (request.getAction()) {
                case CHECK_EXISTS:
                    return serviceClient.connectionExistsWithResponse(connectionId, null).getValue();
                case CLOSE:
                    serviceClient.closeConnectionWithResponse(connectionId, null);
                    return true;
                default:
                    throw ErrorCode.get(ErrorCodes.INVALID_DATA);
            }
        } catch (ErrorCode errorCode) {
            throw errorCode;
        } catch (Exception exception) {
            LOGGER.error("Failed to manage connection [action={}, connectionId={}]",
                    request.getAction(), connectionId, exception);
            throw ErrorCode.get(ErrorCodes.UNKNOWN_ERROR, exception);
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void stop() {
        serviceClient = null;
        LOGGER.info("Azure Web PubSub service stopped");
    }

    /**
     * Resolves the content type string to Azure SDK enum.
     */
    private WebPubSubContentType resolveContentType(final String contentType) {
        if ("text/plain".equalsIgnoreCase(contentType)) {
            return WebPubSubContentType.TEXT_PLAIN;
        }
        return WebPubSubContentType.APPLICATION_JSON;
    }
}

