package com.tlc.notification.service.push;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * <p>
 * Generic request object for push notification operations.
 * The payload type is parameterized with {@code <T>} so callers can send
 * any type (String, JSON object, byte[], custom DTO, etc.) and implementations
 * handle serialization as needed.
 * </p>
 *
 * <p>Extensible via {@link #getOptions()} — any additional parameters can be passed
 * without breaking the interface contract.</p>
 *
 * @param <T> the type of the message payload
 * @version 1.0
 */
public class PushRequest<T> {

    /**
     * Defines how the message should be routed.
     */
    public enum TargetType {
        CONNECTION,
        USER,
        GROUP,
        ALL
    }

    private final TargetType targetType;
    private final String targetId;
    private final T payload;
    private final Map<String, Object> options;

    private PushRequest(final Builder<T> builder) {
        this.targetType = builder.targetType;
        this.targetId = builder.targetId;
        this.payload = builder.payload;
        this.options = Collections.unmodifiableMap(builder.options);
    }

    public TargetType getTargetType() {
        return targetType;
    }

    /**
     * <p>
     * The target identifier (connectionId, userId, or group name depending on {@link #getTargetType()}).
     * May be null for {@link TargetType#ALL}.
     * </p>
     */
    public String getTargetId() {
        return targetId;
    }

    /**
     * <p>
     * The message payload. Type depends on what the caller sends — could be String (JSON),
     * a custom DTO, byte[], etc. The implementation is responsible for handling serialization.
     * </p>
     */
    public T getPayload() {
        return payload;
    }

    /**
     * <p>
     * Extensible options map. Implementations read what they need and ignore the rest.
     * Examples: "contentType", "ttl", "priority", "headers", "excludedConnections", etc.
     * </p>
     */
    public Map<String, Object> getOptions() {
        return options;
    }

    /**
     * <p>
     * Retrieves a typed option value.
     * </p>
     *
     * @param key  the option key
     * @param type the expected value type
     * @param <V>  the return type
     * @return the value or null if not present
     */
    @SuppressWarnings("unchecked")
    public <V> V getOption(final String key, final Class<V> type) {
        final Object value = options.get(key);

        return type.isInstance(value) ? (V) value : null;
    }

    /**
     * <p>
     * Retrieves an option value with a default fallback.
     * </p>
     */
    @SuppressWarnings("unchecked")
    public <V> V getOption(final String key, final V defaultValue) {
        final Object value = options.get(key);

        return value != null ? (V) value : defaultValue;
    }

    public static <T> Builder<T> builder() {
        return new Builder<>();
    }

    /**
     * Builder for constructing {@link PushRequest} instances.
     *
     * @param <T> the type of the message payload
     */
    public static class Builder<T> {

        private TargetType targetType = TargetType.ALL;
        private String targetId;
        private T payload;
        private final Map<String, Object> options = new HashMap<>();

        public Builder<T> targetType(final TargetType targetType) {
            this.targetType = targetType;
            return this;
        }

        public Builder<T> targetId(final String targetId) {
            this.targetId = targetId;
            return this;
        }

        public Builder<T> payload(final T payload) {
            this.payload = payload;
            return this;
        }

        public Builder<T> option(final String key, final Object value) {
            this.options.put(key, value);
            return this;
        }

        public Builder<T> options(final Map<String, Object> options) {
            this.options.putAll(options);
            return this;
        }

        /**
         * Convenience: set target as a specific connection.
         */
        public Builder<T> toConnection(final String connectionId) {
            this.targetType = TargetType.CONNECTION;
            this.targetId = connectionId;
            return this;
        }

        /**
         * Convenience: set target as a specific user.
         */
        public Builder<T> toUser(final String userId) {
            this.targetType = TargetType.USER;
            this.targetId = userId;
            return this;
        }

        /**
         * Convenience: set target as a group.
         */
        public Builder<T> toGroup(final String group) {
            this.targetType = TargetType.GROUP;
            this.targetId = group;
            return this;
        }

        /**
         * Convenience: broadcast to all.
         */
        public Builder<T> toAll() {
            this.targetType = TargetType.ALL;
            this.targetId = null;
            return this;
        }

        public PushRequest<T> build() {
            return new PushRequest<>(this);
        }
    }
}

package com.tlc.notification.service.push;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * <p>
 * Common request object for push notification operations.
 * Carries target info, payload, and extensible options that any implementation can consume.
 * </p>
 *
 * <p>The payload is {@code Object} — callers can pass String (JSON), custom DTOs, byte[], etc.
 * The implementation is responsible for handling serialization.</p>
 *
 * <p>Extensible via {@link #getOptions()} — any additional parameters can be passed
 * without breaking the interface contract.</p>
 *
 * @version 1.0
 */
public class PushRequest {

    /**
     * Defines how the message should be routed.
     */
    public enum TargetType {
        CONNECTION,
        USER,
        GROUP,
        ALL
    }

    private final TargetType targetType;
    private final String targetId;
    private final Object payload;
    private final Map<String, Object> options;

    private PushRequest(final Builder builder) {
        this.targetType = builder.targetType;
        this.targetId = builder.targetId;
        this.payload = builder.payload;
        this.options = Collections.unmodifiableMap(builder.options);
    }

    public TargetType getTargetType() {
        return targetType;
    }

    /**
     * <p>
     * The target identifier (connectionId, userId, or group name depending on {@link #getTargetType()}).
     * May be null for {@link TargetType#ALL}.
     * </p>
     */
    public String getTargetId() {
        return targetId;
    }

    /**
     * <p>
     * The message payload. Can be String (JSON), a custom DTO, byte[], etc.
     * The implementation is responsible for handling serialization.
     * </p>
     */
    public Object getPayload() {
        return payload;
    }

    /**
     * <p>
     * Returns the payload cast to the expected type.
     * </p>
     *
     * @param type the expected payload type
     * @param <T>  the return type
     * @return the typed payload, or null if not matching
     */
    @SuppressWarnings("unchecked")
    public <T> T getPayload(final Class<T> type) {
        return type.isInstance(payload) ? (T) payload : null;
    }

    /**
     * <p>
     * Extensible options map. Implementations read what they need and ignore the rest.
     * Examples: "contentType", "ttl", "priority", "headers", "excludedConnections", etc.
     * </p>
     */
    public Map<String, Object> getOptions() {
        return options;
    }

    /**
     * <p>
     * Retrieves a typed option value.
     * </p>
     *
     * @param key  the option key
     * @param type the expected value type
     * @param <T>  the return type
     * @return the value or null if not present
     */
    @SuppressWarnings("unchecked")
    public <T> T getOption(final String key, final Class<T> type) {
        final Object value = options.get(key);

        return type.isInstance(value) ? (T) value : null;
    }

    /**
     * <p>
     * Retrieves an option value with a default fallback.
     * </p>
     */
    @SuppressWarnings("unchecked")
    public <T> T getOption(final String key, final T defaultValue) {
        final Object value = options.get(key);

        return value != null ? (T) value : defaultValue;
    }

    public static Builder builder() {
        return new Builder();
    }

    /**
     * Builder for constructing {@link PushRequest} instances.
     */
    public static class Builder {

        private TargetType targetType = TargetType.ALL;
        private String targetId;
        private Object payload;
        private final Map<String, Object> options = new HashMap<>();

        public Builder targetType(final TargetType targetType) {
            this.targetType = targetType;
            return this;
        }

        public Builder targetId(final String targetId) {
            this.targetId = targetId;
            return this;
        }

        public Builder payload(final Object payload) {
            this.payload = payload;
            return this;
        }

        public Builder option(final String key, final Object value) {
            this.options.put(key, value);
            return this;
        }

        public Builder options(final Map<String, Object> options) {
            this.options.putAll(options);
            return this;
        }

        /**
         * Convenience: set target as a specific connection.
         */
        public Builder toConnection(final String connectionId) {
            this.targetType = TargetType.CONNECTION;
            this.targetId = connectionId;
            return this;
        }

        /**
         * Convenience: set target as a specific user.
         */
        public Builder toUser(final String userId) {
            this.targetType = TargetType.USER;
            this.targetId = userId;
            return this;
        }

        /**
         * Convenience: set target as a group.
         */
        public Builder toGroup(final String group) {
            this.targetType = TargetType.GROUP;
            this.targetId = group;
            return this;
        }

        /**
         * Convenience: broadcast to all.
         */
        public Builder toAll() {
            this.targetType = TargetType.ALL;
            this.targetId = null;
            return this;
        }

        public PushRequest build() {
            return new PushRequest(this);
        }
    }
}
